/// Private chat and call (Task 68). Order: en, hi, hinglish, kn, ta, te, mr, gu, bn, pa, ks, ur.
const Map<String, List<String>> privateCommStrings = {
  'pcTooMany': ['Too many calls this hour. Try again later or send a chat message.', 'इस घंटे बहुत कॉल हो गईं। बाद में कोशिश करें या चैट भेजें।', 'Is ghante bahut calls ho gayi. Baad mein koshish karein ya chat bhejein.', 'ಈ ಗಂಟೆ ತುಂಬಾ ಕರೆಗಳಾಗಿವೆ. ನಂತರ ಪ್ರಯತ್ನಿಸಿ ಅಥವಾ ಚಾಟ್ ಕಳುಹಿಸಿ.', 'இந்த மணி நேரத்தில் அதிக அழைப்புகள். பிறகு முயலவும் அல்லது அரட்டை அனுப்பவும்.', 'ఈ గంటలో చాలా కాల్స్ అయ్యాయి. తర్వాత ప్రయత్నించండి లేదా చాట్ పంపండి.', 'या तासात खूप कॉल झाले. नंतर प्रयत्न करा किंवा चॅट पाठवा.', 'આ કલાકમાં ઘણા કૉલ થયા. પછી પ્રયાસ કરો અથવા ચેટ મોકલો.', 'এই ঘণ্টায় অনেক কল হয়েছে। পরে চেষ্টা করুন বা চ্যাট পাঠান।', 'ਇਸ ਘੰਟੇ ਬਹੁਤ ਕਾਲਾਂ ਹੋ ਗਈਆਂ। ਬਾਅਦ ਵਿੱਚ ਕੋਸ਼ਿਸ਼ ਕਰੋ ਜਾਂ ਚੈਟ ਭੇਜੋ।', 'یم گنٹہ بہت کال۔ پتہٕ کوشش کرو یا چیٹ ہیو۔', 'اس گھنٹے بہت کالیں ہو گئیں۔ بعد میں کوشش کریں یا چیٹ بھیجیں۔'],
  'notifTripAssigned': ['A transporter gave you a trip', 'ट्रांसपोर्टर ने आपको ट्रिप दी', 'Transporter ne aapko trip di', 'ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್ ನಿಮಗೆ ಟ್ರಿಪ್ ನೀಡಿದ್ದಾರೆ', 'டிரான்ஸ்போர்ட்டர் உங்களுக்கு பயணம் வழங்கினார்', 'ట్రాన్స్‌పోర్టర్ మీకు ట్రిప్ ఇచ్చారు', 'ट्रान्सपोर्टरने तुम्हाला ट्रिप दिली', 'ટ્રાન્સપોર્ટરે તમને ટ્રિપ આપી', 'ট্রান্সপোর্টার আপনাকে ট্রিপ দিয়েছেন', 'ਟ੍ਰਾਂਸਪੋਰਟਰ ਨੇ ਤੁਹਾਨੂੰ ਟ੍ਰਿਪ ਦਿੱਤੀ', 'ٹرانسپورٹر دوٚت توہہ ٹرپ', 'ٹرانسپورٹر نے آپ کو ٹرپ دی'],
  'notifMissedCall': ['Missed call', 'मिस्ड कॉल', 'Missed call', 'ತಪ್ಪಿದ ಕರೆ', 'தவறிய அழைப்பு', 'మిస్డ్ కాల్', 'मिस्ड कॉल', 'મિસ્ડ કૉલ', 'মিসড কল', 'ਮਿਸਡ ਕਾਲ', 'مِس کال', 'مس کال'],
  'asContact': ['Phone numbers are private on {app}. Use Chat and the Call button on the trip screen: the call goes through the app and nobody sees a number. Messages with a phone number, UPI id or WhatsApp are blocked, and repeated attempts pause chat and calls for 24 hours, then 3 days, then 7 days. SOS always works.', '{app} पर फ़ोन नंबर निजी हैं। ट्रिप स्क्रीन पर चैट और कॉल बटन इस्तेमाल करें: कॉल ऐप से जाती है और किसी को नंबर नहीं दिखता। फ़ोन नंबर, UPI आईडी या WhatsApp वाले संदेश रोक दिए जाते हैं, और बार-बार कोशिश पर चैट और कॉल 24 घंटे, फिर 3 दिन, फिर 7 दिन बंद हो जाते हैं। SOS हमेशा चलता है।', '{app} par phone number private hain. Trip screen par Chat aur Call button use karein: call app se jaati hai aur kisi ko number nahi dikhta. Phone number, UPI id ya WhatsApp wale message rok diye jaate hain, aur baar-baar koshish par chat aur call 24 ghante, phir 3 din, phir 7 din band ho jaate hain. SOS hamesha chalta hai.', '{app} ನಲ್ಲಿ ಫೋನ್ ಸಂಖ್ಯೆ ಖಾಸಗಿ. ಟ್ರಿಪ್ ಪರದೆಯಲ್ಲಿ ಚಾಟ್ ಮತ್ತು ಕರೆ ಬಟನ್ ಬಳಸಿ: ಕರೆ ಆ್ಯಪ್ ಮೂಲಕ ಹೋಗುತ್ತದೆ, ಯಾರಿಗೂ ಸಂಖ್ಯೆ ಕಾಣುವುದಿಲ್ಲ. ಫೋನ್ ಸಂಖ್ಯೆ, UPI ಐಡಿ, WhatsApp ಇರುವ ಸಂದೇಶ ತಡೆಯಲಾಗುತ್ತದೆ; ಮತ್ತೆ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿದರೆ ಚಾಟ್ ಮತ್ತು ಕರೆ 24 ಗಂಟೆ, ನಂತರ 3 ದಿನ, ನಂತರ 7 ದಿನ ನಿಲ್ಲುತ್ತದೆ. SOS ಯಾವಾಗಲೂ ಕೆಲಸ ಮಾಡುತ್ತದೆ.', '{app} இல் தொலைபேசி எண்கள் தனிப்பட்டவை. பயணத் திரையில் அரட்டை, அழைப்பு பொத்தானைப் பயன்படுத்துங்கள்: அழைப்பு செயலி வழியாகப் போகும், யாருக்கும் எண் தெரியாது. தொலைபேசி எண், UPI ஐடி, WhatsApp உள்ள செய்திகள் தடுக்கப்படும்; மீண்டும் மீண்டும் முயன்றால் அரட்டை, அழைப்பு 24 மணி நேரம், பிறகு 3 நாள், பிறகு 7 நாள் நிறுத்தப்படும். SOS எப்போதும் வேலை செய்யும்.', '{app} లో ఫోన్ నంబర్లు ప్రైవేట్. ట్రిప్ స్క్రీన్‌లో చాట్, కాల్ బటన్ వాడండి: కాల్ యాప్ ద్వారా వెళ్తుంది, ఎవరికీ నంబర్ కనిపించదు. ఫోన్ నంబర్, UPI ఐడి, WhatsApp ఉన్న సందేశాలు ఆపబడతాయి; పదే పదే ప్రయత్నిస్తే చాట్, కాల్ 24 గంటలు, తర్వాత 3 రోజులు, తర్వాత 7 రోజులు ఆగుతాయి. SOS ఎప్పుడూ పనిచేస్తుంది.', '{app} वर फोन नंबर खाजगी आहेत. ट्रिप स्क्रीनवर चॅट आणि कॉल बटण वापरा: कॉल अ‍ॅपमधून जातो, कोणालाही नंबर दिसत नाही. फोन नंबर, UPI आयडी, WhatsApp असलेले संदेश थांबवले जातात; वारंवार प्रयत्न केल्यास चॅट आणि कॉल 24 तास, मग 3 दिवस, मग 7 दिवस बंद होतात. SOS नेहमी चालते.', '{app} પર ફોન નંબર ખાનગી છે. ટ્રિપ સ્ક્રીન પર ચેટ અને કૉલ બટન વાપરો: કૉલ એપ દ્વારા જાય છે, કોઈને નંબર દેખાતો નથી. ફોન નંબર, UPI આઈડી, WhatsApp વાળા સંદેશ રોકાય છે; વારંવાર પ્રયાસથી ચેટ અને કૉલ 24 કલાક, પછી 3 દિવસ, પછી 7 દિવસ બંધ થાય છે. SOS હંમેશા ચાલે છે.', '{app}-তে ফোন নম্বর গোপন। ট্রিপ স্ক্রিনে চ্যাট ও কল বোতাম ব্যবহার করুন: কল অ্যাপের মাধ্যমে যায়, কেউ নম্বর দেখে না। ফোন নম্বর, UPI আইডি, WhatsApp থাকা বার্তা আটকে যায়; বারবার চেষ্টা করলে চ্যাট ও কল ২৪ ঘণ্টা, তারপর ৩ দিন, তারপর ৭ দিন বন্ধ থাকে। SOS সবসময় চলে।', '{app} ਤੇ ਫ਼ੋਨ ਨੰਬਰ ਨਿੱਜੀ ਹਨ। ਟ੍ਰਿਪ ਸਕ੍ਰੀਨ ਤੇ ਚੈਟ ਅਤੇ ਕਾਲ ਬਟਨ ਵਰਤੋ: ਕਾਲ ਐਪ ਰਾਹੀਂ ਜਾਂਦੀ ਹੈ, ਕਿਸੇ ਨੂੰ ਨੰਬਰ ਨਹੀਂ ਦਿਸਦਾ। ਫ਼ੋਨ ਨੰਬਰ, UPI ਆਈਡੀ, WhatsApp ਵਾਲੇ ਸੁਨੇਹੇ ਰੋਕੇ ਜਾਂਦੇ ਹਨ; ਵਾਰ-ਵਾਰ ਕੋਸ਼ਿਸ਼ ਤੇ ਚੈਟ ਅਤੇ ਕਾਲ 24 ਘੰਟੇ, ਫਿਰ 3 ਦਿਨ, ਫਿਰ 7 ਦਿਨ ਬੰਦ ਰਹਿੰਦੇ ਹਨ। SOS ਹਮੇਸ਼ਾ ਚੱਲਦਾ ਹੈ।', '{app} پیٹھ فون نمبر نجی چھ۔ ٹرپ سکرینس پیٹھ چیٹ تہٕ کال بٹن استعمال کرو: کال چھ ایپ ذریعہ گژھان، کُنہِ نمبر ناہ ووچھان۔ فون نمبر، UPI آئی ڈی، WhatsApp والۍ پیغام چھ روکان؛ بار بار کوشش پیٹھ چیٹ تہٕ کال 24 گنٹہ، پتہٕ 3 دۄہ، پتہٕ 7 دۄہ بند۔ SOS چھ ہمیشہ کم کران۔', '{app} پر فون نمبر نجی ہیں۔ ٹرپ اسکرین پر چیٹ اور کال بٹن استعمال کریں: کال ایپ کے ذریعے جاتی ہے، کسی کو نمبر نظر نہیں آتا۔ فون نمبر، UPI آئی ڈی یا WhatsApp والے پیغام روک دیے جاتے ہیں، اور بار بار کوشش پر چیٹ اور کال 24 گھنٹے، پھر 3 دن، پھر 7 دن بند رہتے ہیں۔ SOS ہمیشہ چلتا ہے۔'],
  'faqQ9': ['Why can\'t I see the other person\'s phone number?', 'दूसरे का फ़ोन नंबर क्यों नहीं दिखता?', 'Doosre ka phone number kyun nahi dikhta?', 'ಇನ್ನೊಬ್ಬರ ಫೋನ್ ಸಂಖ್ಯೆ ಏಕೆ ಕಾಣುವುದಿಲ್ಲ?', 'மற்றவரின் தொலைபேசி எண் ஏன் தெரியவில்லை?', 'అవతలి వ్యక్తి ఫోన్ నంబర్ ఎందుకు కనిపించదు?', 'दुसऱ्याचा फोन नंबर का दिसत नाही?', 'સામેવાળાનો ફોન નંબર કેમ દેખાતો નથી?', 'অন্যজনের ফোন নম্বর কেন দেখা যায় না?', 'ਦੂਜੇ ਦਾ ਫ਼ੋਨ ਨੰਬਰ ਕਿਉਂ ਨਹੀਂ ਦਿਸਦਾ?', 'بییسند فون نمبر کیازِ ناہ ووچھان؟', 'دوسرے کا فون نمبر کیوں نظر نہیں آتا؟'],
  'faqA9': ['Numbers are private so that nobody is called or messaged outside the app. Use Chat and the Call button on the trip screen. If a call is not picked up, send a chat message: calls ring only while the other person has the app open.', 'नंबर निजी रखे जाते हैं ताकि ऐप के बाहर किसी को कॉल या संदेश न जाए। ट्रिप स्क्रीन पर चैट और कॉल बटन इस्तेमाल करें। कॉल न उठे तो चैट भेजें: कॉल तभी बजती है जब सामने वाले का ऐप खुला हो।', 'Number private rakhe jaate hain taaki app ke bahar kisi ko call ya message na jaye. Trip screen par Chat aur Call button use karein. Call na uthe to chat bhejein: call tabhi bajti hai jab samne wale ka app khula ho.', 'ಆ್ಯಪ್ ಹೊರಗೆ ಯಾರಿಗೂ ಕರೆ ಅಥವಾ ಸಂದೇಶ ಹೋಗದಂತೆ ಸಂಖ್ಯೆಗಳು ಖಾಸಗಿ. ಟ್ರಿಪ್ ಪರದೆಯಲ್ಲಿ ಚಾಟ್ ಮತ್ತು ಕರೆ ಬಟನ್ ಬಳಸಿ. ಕರೆ ಎತ್ತದಿದ್ದರೆ ಚಾಟ್ ಕಳುಹಿಸಿ: ಇನ್ನೊಬ್ಬರ ಆ್ಯಪ್ ತೆರೆದಿದ್ದರೆ ಮಾತ್ರ ಕರೆ ರಿಂಗ್ ಆಗುತ್ತದೆ.', 'செயலிக்கு வெளியே யாருக்கும் அழைப்பு அல்லது செய்தி போகாமல் இருக்க எண்கள் தனிப்பட்டவை. பயணத் திரையில் அரட்டை, அழைப்பு பொத்தானைப் பயன்படுத்துங்கள். அழைப்பை எடுக்கவில்லையெனில் அரட்டை அனுப்புங்கள்: மற்றவரின் செயலி திறந்திருக்கும்போது மட்டுமே அழைப்பு ஒலிக்கும்.', 'యాప్ బయట ఎవరికీ కాల్ లేదా సందేశం వెళ్లకుండా నంబర్లు ప్రైవేట్. ట్రిప్ స్క్రీన్‌లో చాట్, కాల్ బటన్ వాడండి. కాల్ ఎత్తకపోతే చాట్ పంపండి: అవతలి వ్యక్తి యాప్ తెరిచి ఉంటేనే కాల్ రింగ్ అవుతుంది.', 'अ‍ॅपबाहेर कोणालाही कॉल किंवा संदेश जाऊ नये म्हणून नंबर खाजगी ठेवले आहेत. ट्रिप स्क्रीनवर चॅट आणि कॉल बटण वापरा. कॉल उचलला नाही तर चॅट पाठवा: समोरच्याचे अ‍ॅप उघडे असेल तेव्हाच कॉल वाजतो.', 'એપ બહાર કોઈને કૉલ કે સંદેશ ન જાય તે માટે નંબર ખાનગી રાખ્યા છે. ટ્રિપ સ્ક્રીન પર ચેટ અને કૉલ બટન વાપરો. કૉલ ન ઉપડે તો ચેટ મોકલો: સામેવાળાની એપ ખુલ્લી હોય ત્યારે જ કૉલ વાગે છે.', 'অ্যাপের বাইরে কাউকে কল বা বার্তা না যায় তাই নম্বর গোপন রাখা হয়। ট্রিপ স্ক্রিনে চ্যাট ও কল বোতাম ব্যবহার করুন। কল না ধরলে চ্যাট পাঠান: অন্যজনের অ্যাপ খোলা থাকলেই কল বাজে।', 'ਐਪ ਤੋਂ ਬਾਹਰ ਕਿਸੇ ਨੂੰ ਕਾਲ ਜਾਂ ਸੁਨੇਹਾ ਨਾ ਜਾਵੇ, ਇਸ ਲਈ ਨੰਬਰ ਨਿੱਜੀ ਰੱਖੇ ਹਨ। ਟ੍ਰਿਪ ਸਕ੍ਰੀਨ ਤੇ ਚੈਟ ਅਤੇ ਕਾਲ ਬਟਨ ਵਰਤੋ। ਕਾਲ ਨਾ ਚੁੱਕੀ ਜਾਵੇ ਤਾਂ ਚੈਟ ਭੇਜੋ: ਕਾਲ ਤਦ ਹੀ ਵੱਜਦੀ ਹੈ ਜਦੋਂ ਦੂਜੇ ਦੀ ਐਪ ਖੁੱਲ੍ਹੀ ਹੋਵੇ।', 'ایپ برونہہ کُنہِ کال یا پیغام مہ گژھہِ، یتھ خاطرٕ نمبر نجی چھ۔ ٹرپ سکرینس پیٹھ چیٹ تہٕ کال بٹن استعمال کرو۔ کال ناہ اُٹھنہ پیٹھ چیٹ ہیو: کال تیلہ وچھہ ییلہ بییس ہندۍ ایپ کھُلۍ ہیو۔', 'ایپ کے باہر کسی کو کال یا پیغام نہ جائے اس لیے نمبر نجی رکھے گئے ہیں۔ ٹرپ اسکرین پر چیٹ اور کال بٹن استعمال کریں۔ کال نہ اٹھے تو چیٹ بھیجیں: کال تب ہی بجتی ہے جب سامنے والے کی ایپ کھلی ہو۔'],
  'faqQ10': ['Why was my message blocked?', 'मेरा संदेश क्यों रोका गया?', 'Mera message kyun roka gaya?', 'ನನ್ನ ಸಂದೇಶ ಏಕೆ ತಡೆಯಲಾಯಿತು?', 'என் செய்தி ஏன் தடுக்கப்பட்டது?', 'నా సందేశం ఎందుకు ఆపబడింది?', 'माझा संदेश का थांबवला?', 'મારો સંદેશ કેમ રોકાયો?', 'আমার বার্তা কেন আটকানো হল?', 'ਮੇਰਾ ਸੁਨੇਹਾ ਕਿਉਂ ਰੋਕਿਆ ਗਿਆ?', 'میون پیغام کیازِ روکُن؟', 'میرا پیغام کیوں روکا گیا؟'],
  'faqA10': ['Messages with a phone number, UPI id, WhatsApp or Telegram, a link, or "call me" are not sent. The first two times you get a warning. After that chat and calls are paused: 24 hours, then 3 days, then 7 days with an admin review. After 30 clean days a strike is removed. SOS always works.', 'फ़ोन नंबर, UPI आईडी, WhatsApp या Telegram, लिंक या "कॉल करो" वाले संदेश नहीं भेजे जाते। पहली दो बार चेतावनी मिलती है। उसके बाद चैट और कॉल बंद हो जाते हैं: 24 घंटे, फिर 3 दिन, फिर 7 दिन एडमिन समीक्षा के साथ। 30 साफ दिन बाद एक स्ट्राइक हटती है। SOS हमेशा चलता है।', 'Phone number, UPI id, WhatsApp ya Telegram, link ya "call me" wale message nahi bheje jaate. Pehli do baar chetavni milti hai. Uske baad chat aur call band: 24 ghante, phir 3 din, phir 7 din admin review ke saath. 30 saaf din baad ek strike hatti hai. SOS hamesha chalta hai.', 'ಫೋನ್ ಸಂಖ್ಯೆ, UPI ಐಡಿ, WhatsApp ಅಥವಾ Telegram, ಲಿಂಕ್ ಅಥವಾ "ಕರೆ ಮಾಡಿ" ಇರುವ ಸಂದೇಶ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ. ಮೊದಲ ಎರಡು ಬಾರಿ ಎಚ್ಚರಿಕೆ. ನಂತರ ಚಾಟ್ ಮತ್ತು ಕರೆ ನಿಲ್ಲುತ್ತದೆ: 24 ಗಂಟೆ, ನಂತರ 3 ದಿನ, ನಂತರ 7 ದಿನ ಪರಿಶೀಲನೆಯೊಂದಿಗೆ. 30 ಸ್ವಚ್ಛ ದಿನಗಳ ನಂತರ ಒಂದು ಸ್ಟ್ರೈಕ್ ಹೋಗುತ್ತದೆ. SOS ಯಾವಾಗಲೂ ಕೆಲಸ ಮಾಡುತ್ತದೆ.', 'தொலைபேசி எண், UPI ஐடி, WhatsApp அல்லது Telegram, இணைப்பு அல்லது "அழைக்கவும்" உள்ள செய்திகள் அனுப்பப்படாது. முதல் இரண்டு முறை எச்சரிக்கை. பிறகு அரட்டை, அழைப்பு நிறுத்தம்: 24 மணி நேரம், பிறகு 3 நாள், பிறகு 7 நாள் மதிப்பாய்வுடன். 30 தூய நாட்களுக்குப் பிறகு ஒரு ஸ்ட்ரைக் நீங்கும். SOS எப்போதும் வேலை செய்யும்.', 'ఫోన్ నంబర్, UPI ఐడి, WhatsApp లేదా Telegram, లింక్ లేదా "కాల్ చేయండి" ఉన్న సందేశాలు పంపబడవు. మొదటి రెండు సార్లు హెచ్చరిక. తర్వాత చాట్, కాల్ ఆగుతాయి: 24 గంటలు, తర్వాత 3 రోజులు, తర్వాత 7 రోజులు సమీక్షతో. 30 శుభ్రమైన రోజుల తర్వాత ఒక స్ట్రైక్ తొలగుతుంది. SOS ఎప్పుడూ పనిచేస్తుంది.', 'फोन नंबर, UPI आयडी, WhatsApp किंवा Telegram, लिंक किंवा "कॉल करा" असलेले संदेश पाठवले जात नाहीत. पहिल्या दोन वेळा इशारा. नंतर चॅट आणि कॉल बंद: 24 तास, मग 3 दिवस, मग 7 दिवस तपासणीसह. 30 स्वच्छ दिवसांनंतर एक स्ट्राइक जातो. SOS नेहमी चालते.', 'ફોન નંબર, UPI આઈડી, WhatsApp કે Telegram, લિંક કે "કૉલ કરો" વાળા સંદેશ મોકલાતા નથી. પહેલી બે વાર ચેતવણી. પછી ચેટ અને કૉલ બંધ: 24 કલાક, પછી 3 દિવસ, પછી 7 દિવસ સમીક્ષા સાથે. 30 સ્વચ્છ દિવસ પછી એક સ્ટ્રાઇક હટે છે. SOS હંમેશા ચાલે છે.', 'ফোন নম্বর, UPI আইডি, WhatsApp বা Telegram, লিংক বা "কল করুন" থাকা বার্তা পাঠানো হয় না। প্রথম দুবার সতর্কতা। তারপর চ্যাট ও কল বন্ধ: ২৪ ঘণ্টা, তারপর ৩ দিন, তারপর ৭ দিন পর্যালোচনাসহ। ৩০ পরিষ্কার দিন পরে একটি স্ট্রাইক কমে। SOS সবসময় চলে।', 'ਫ਼ੋਨ ਨੰਬਰ, UPI ਆਈਡੀ, WhatsApp ਜਾਂ Telegram, ਲਿੰਕ ਜਾਂ "ਕਾਲ ਕਰੋ" ਵਾਲੇ ਸੁਨੇਹੇ ਨਹੀਂ ਭੇਜੇ ਜਾਂਦੇ। ਪਹਿਲੀਆਂ ਦੋ ਵਾਰ ਚੇਤਾਵਨੀ। ਫਿਰ ਚੈਟ ਅਤੇ ਕਾਲ ਬੰਦ: 24 ਘੰਟੇ, ਫਿਰ 3 ਦਿਨ, ਫਿਰ 7 ਦਿਨ ਸਮੀਖਿਆ ਸਮੇਤ। 30 ਸਾਫ਼ ਦਿਨਾਂ ਬਾਅਦ ਇੱਕ ਸਟ੍ਰਾਈਕ ਹਟਦੀ ਹੈ। SOS ਹਮੇਸ਼ਾ ਚੱਲਦਾ ਹੈ।', 'فون نمبر، UPI آئی ڈی، WhatsApp یا Telegram، لنک یا "کال کرو" والۍ پیغام چھ ناہ روانہ گژھان۔ پؠٹھمین دۄن کھوٚتھ خبردار۔ پتہٕ چیٹ تہٕ کال بند: 24 گنٹہ، پتہٕ 3 دۄہ، پتہٕ 7 دۄہ ریویو سان۔ 30 صاف دۄہ پتہٕ اکھ سٹرائک ہٹان۔ SOS چھ ہمیشہ کم کران۔', 'فون نمبر، UPI آئی ڈی، WhatsApp یا Telegram، لنک یا "کال کریں" والے پیغام نہیں بھیجے جاتے۔ پہلی دو بار وارننگ ملتی ہے۔ اس کے بعد چیٹ اور کال بند: 24 گھنٹے، پھر 3 دن، پھر 7 دن جائزے کے ساتھ۔ 30 صاف دن بعد ایک اسٹرائیک ہٹتی ہے۔ SOS ہمیشہ چلتا ہے۔'],
  'faqQ11': ['What is a Transporter and the Verified badge?', 'ट्रांसपोर्टर और सत्यापित बैज क्या है?', 'Transporter aur Verified badge kya hai?', 'ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್ ಮತ್ತು ಪರಿಶೀಲಿತ ಬ್ಯಾಡ್ಜ್ ಎಂದರೇನು?', 'டிரான்ஸ்போர்ட்டர், சரிபார்க்கப்பட்ட பேட்ஜ் என்றால் என்ன?', 'ట్రాన్స్‌పోర్టర్, ధృవీకరించిన బ్యాడ్జ్ అంటే ఏమిటి?', 'ट्रान्सपोर्टर आणि सत्यापित बॅज म्हणजे काय?', 'ટ્રાન્સપોર્ટર અને ચકાસાયેલ બેજ શું છે?', 'ট্রান্সপোর্টার ও যাচাইকৃত ব্যাজ কী?', 'ਟ੍ਰਾਂਸਪੋਰਟਰ ਅਤੇ ਪੜਤਾਲਿਆ ਬੈਜ ਕੀ ਹੈ?', 'ٹرانسپورٹر تہٕ تصدیق شدہ بیج کیا چھ؟', 'ٹرانسپورٹر اور تصدیق شدہ بیج کیا ہے؟'],
  'faqA11': ['A Transporter is a company with several trucks and drivers. It bids for a load, and after the customer picks the bid it assigns a vehicle and one of its drivers. "Verified transporter" means an admin checked the company. Your driver, vehicle number and rating are always shown.', 'ट्रांसपोर्टर कई ट्रक और ड्राइवर वाली कंपनी है। वह लोड पर बोली लगाती है और ग्राहक के चुनने पर वाहन और अपना ड्राइवर सौंपती है। "सत्यापित ट्रांसपोर्टर" का मतलब एडमिन ने कंपनी जाँची है। आपको ड्राइवर, गाड़ी नंबर और रेटिंग हमेशा दिखती है।', 'Transporter kai trucks aur drivers wali company hai. Woh load par bid lagati hai aur customer ke chunne par vehicle aur apna driver assign karti hai. "Verified transporter" ka matlab admin ne company check ki hai. Aapko driver, gaadi number aur rating hamesha dikhti hai.', 'ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್ ಹಲವು ಟ್ರಕ್ ಮತ್ತು ಚಾಲಕರಿರುವ ಕಂಪನಿ. ಲೋಡ್‌ಗೆ ಬಿಡ್ ಮಾಡುತ್ತದೆ, ಗ್ರಾಹಕರು ಆರಿಸಿದ ನಂತರ ವಾಹನ ಮತ್ತು ತನ್ನ ಚಾಲಕರನ್ನು ನೀಡುತ್ತದೆ. "ಪರಿಶೀಲಿತ ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್" ಎಂದರೆ ನಿರ್ವಾಹಕರು ಕಂಪನಿಯನ್ನು ಪರಿಶೀಲಿಸಿದ್ದಾರೆ. ಚಾಲಕ, ವಾಹನ ಸಂಖ್ಯೆ, ರೇಟಿಂಗ್ ಯಾವಾಗಲೂ ಕಾಣುತ್ತದೆ.', 'டிரான்ஸ்போர்ட்டர் பல லாரிகளும் ஓட்டுநர்களும் உள்ள நிறுவனம். சரக்குக்கு ஏலம் எடுத்து, வாடிக்கையாளர் தேர்ந்தபின் வாகனத்தையும் தன் ஓட்டுநரையும் நியமிக்கும். "சரிபார்க்கப்பட்ட டிரான்ஸ்போர்ட்டர்" என்றால் நிர்வாகி நிறுவனத்தைச் சரிபார்த்தார். ஓட்டுநர், வாகன எண், மதிப்பீடு எப்போதும் தெரியும்.', 'ట్రాన్స్‌పోర్టర్ అనేక ట్రక్కులు, డ్రైవర్లు ఉన్న కంపెనీ. లోడ్‌కు బిడ్ వేసి, కస్టమర్ ఎంచుకున్నాక వాహనం, తన డ్రైవర్‌ను కేటాయిస్తుంది. "ధృవీకరించిన ట్రాన్స్‌పోర్టర్" అంటే అడ్మిన్ కంపెనీని తనిఖీ చేశారు. డ్రైవర్, వాహన నంబర్, రేటింగ్ ఎప్పుడూ కనిపిస్తాయి.', 'ट्रान्सपोर्टर म्हणजे अनेक ट्रक आणि ड्रायव्हर असलेली कंपनी. ती लोडवर बोली लावते आणि ग्राहकाने निवडल्यावर वाहन व स्वतःचा ड्रायव्हर नेमते. "सत्यापित ट्रान्सपोर्टर" म्हणजे अ‍ॅडमिनने कंपनी तपासली. ड्रायव्हर, वाहन क्रमांक आणि रेटिंग नेहमी दिसते.', 'ટ્રાન્સપોર્ટર એટલે ઘણા ટ્રક અને ડ્રાઇવર ધરાવતી કંપની. તે લોડ પર બિડ કરે છે અને ગ્રાહક પસંદ કરે પછી વાહન અને પોતાનો ડ્રાઇવર સોંપે છે. "ચકાસાયેલ ટ્રાન્સપોર્ટર" એટલે એડમિને કંપની તપાસી છે. ડ્રાઇવર, વાહન નંબર અને રેટિંગ હંમેશા દેખાય છે.', 'ট্রান্সপোর্টার অনেক ট্রাক ও ড্রাইভারওয়ালা কোম্পানি। সে লোডে বিড করে, গ্রাহক বাছলে গাড়ি ও নিজের ড্রাইভার দেয়। "যাচাইকৃত ট্রান্সপোর্টার" মানে অ্যাডমিন কোম্পানি যাচাই করেছেন। ড্রাইভার, গাড়ির নম্বর ও রেটিং সবসময় দেখা যায়।', 'ਟ੍ਰਾਂਸਪੋਰਟਰ ਕਈ ਟਰੱਕਾਂ ਅਤੇ ਡਰਾਈਵਰਾਂ ਵਾਲੀ ਕੰਪਨੀ ਹੈ। ਉਹ ਲੋਡ ਤੇ ਬੋਲੀ ਲਾਉਂਦੀ ਹੈ ਅਤੇ ਗਾਹਕ ਦੇ ਚੁਣਨ ਤੇ ਵਾਹਨ ਅਤੇ ਆਪਣਾ ਡਰਾਈਵਰ ਸੌਂਪਦੀ ਹੈ। "ਪੜਤਾਲਿਆ ਟ੍ਰਾਂਸਪੋਰਟਰ" ਦਾ ਮਤਲਬ ਐਡਮਿਨ ਨੇ ਕੰਪਨੀ ਜਾਂਚੀ ਹੈ। ਡਰਾਈਵਰ, ਗੱਡੀ ਨੰਬਰ ਅਤੇ ਰੇਟਿੰਗ ਹਮੇਸ਼ਾ ਦਿਸਦੇ ਹਨ।', 'ٹرانسپورٹر چھ کمپنی یمس بہت ٹرک تہٕ ڈرائیور چھ۔ یہ لوڈس پیٹھ بولی لاگان تہٕ گاہک ژارنہ پتہٕ گاڈی تہٕ پننہ ڈرائیور مقرر کران۔ "تصدیق شدہ ٹرانسپورٹر" مطلب ایڈمن دوٚت کمپنی وُچھ۔ ڈرائیور، گاڈی نمبر تہٕ ریٹنگ چھ ہمیشہ نظر یوان۔', 'ٹرانسپورٹر کئی ٹرکوں اور ڈرائیوروں والی کمپنی ہے۔ وہ لوڈ پر بولی لگاتی ہے اور گاہک کے چننے پر گاڑی اور اپنا ڈرائیور مقرر کرتی ہے۔ "تصدیق شدہ ٹرانسپورٹر" کا مطلب ایڈمن نے کمپنی جانچی ہے۔ ڈرائیور، گاڑی نمبر اور ریٹنگ ہمیشہ نظر آتی ہے۔'],
  'pcOk': ['OK', 'ठीक है', 'Theek hai', 'ಸರಿ', 'சரி', 'సరే', 'ठीक आहे', 'ઠીક છે', 'ঠিক আছে', 'ਠੀਕ ਹੈ', 'ٹھیک', 'ٹھیک ہے'],
  'pcDone': ['Done', 'हो गया', 'Ho gaya', 'ಮುಗಿದಿದೆ', 'முடிந்தது', 'అయింది', 'झाले', 'થઈ ગયું', 'হয়েছে', 'ਹੋ ਗਿਆ', 'مکمل', 'ہو گیا'],
  'pcChatNote': ['Phone numbers stay private on {app}. Chat here or use the call button.', '{app} पर फ़ोन नंबर निजी रहते हैं। यहीं चैट करें या कॉल बटन दबाएँ।', '{app} par phone number private rehte hain. Yahin chat karein ya call button dabayein.', '{app} ನಲ್ಲಿ ಫೋನ್ ಸಂಖ್ಯೆಗಳು ಖಾಸಗಿ. ಇಲ್ಲೇ ಚಾಟ್ ಮಾಡಿ ಅಥವಾ ಕರೆ ಬಟನ್ ಒತ್ತಿ.', '{app} இல் தொலைபேசி எண்கள் தனிப்பட்டவை. இங்கேயே அரட்டை அடியுங்கள் அல்லது அழைப்பு பொத்தானை அழுத்துங்கள்.', '{app} లో ఫోన్ నంబర్లు ప్రైవేట్. ఇక్కడే చాట్ చేయండి లేదా కాల్ బటన్ నొక్కండి.', '{app} वर फोन नंबर खाजगी राहतात. इथेच चॅट करा किंवा कॉल बटण दाबा.', '{app} પર ફોન નંબર ખાનગી રહે છે. અહીં જ ચેટ કરો અથવા કૉલ બટન દબાવો.', '{app}-তে ফোন নম্বর গোপন থাকে। এখানেই চ্যাট করুন বা কল বোতাম চাপুন।', '{app} ਤੇ ਫ਼ੋਨ ਨੰਬਰ ਨਿੱਜੀ ਰਹਿੰਦੇ ਹਨ। ਇੱਥੇ ਹੀ ਚੈਟ ਕਰੋ ਜਾਂ ਕਾਲ ਬਟਨ ਦਬਾਓ।', '{app} پیٹھ فون نمبر نجی روزن۔ یتھ چیٹ کرو یا کال بٹن دبو۔', '{app} پر فون نمبر نجی رہتے ہیں۔ یہیں چیٹ کریں یا کال بٹن دبائیں۔'],
  'pcWarnTitle': ['Message not sent', 'संदेश नहीं भेजा गया', 'Message nahi bheja gaya', 'ಸಂದೇಶ ಕಳುಹಿಸಿಲ್ಲ', 'செய்தி அனுப்பப்படவில்லை', 'సందేశం పంపలేదు', 'संदेश पाठवला नाही', 'સંદેશ મોકલાયો નથી', 'বার্তা পাঠানো হয়নি', 'ਸੁਨੇਹਾ ਨਹੀਂ ਭੇਜਿਆ', 'پیغام ناہ ہیوٕ', 'پیغام نہیں بھیجا گیا'],
  'pcWarnBody': ['Phone numbers, UPI ids, WhatsApp, Telegram and "call me" are not allowed, for everyone\'s safety. Use the in-app chat and call. Warning {n} of 2.', 'सबकी सुरक्षा के लिए फ़ोन नंबर, UPI आईडी, WhatsApp, Telegram और "कॉल करो" की अनुमति नहीं है। ऐप की चैट और कॉल इस्तेमाल करें। चेतावनी {n}/2।', 'Sabki suraksha ke liye phone number, UPI id, WhatsApp, Telegram aur "call me" allowed nahi. App ki chat aur call use karein. Chetavni {n}/2.', 'ಎಲ್ಲರ ಸುರಕ್ಷತೆಗಾಗಿ ಫೋನ್ ಸಂಖ್ಯೆ, UPI ಐಡಿ, WhatsApp, Telegram ಮತ್ತು "ಕರೆ ಮಾಡಿ" ಅನುಮತಿ ಇಲ್ಲ. ಆ್ಯಪ್ ಚಾಟ್ ಮತ್ತು ಕರೆ ಬಳಸಿ. ಎಚ್ಚರಿಕೆ {n}/2.', 'அனைவரின் பாதுகாப்புக்காக தொலைபேசி எண், UPI ஐடி, WhatsApp, Telegram, "அழைக்கவும்" அனுமதி இல்லை. செயலியின் அரட்டை, அழைப்பைப் பயன்படுத்தவும். எச்சரிக்கை {n}/2.', 'అందరి భద్రత కోసం ఫోన్ నంబర్, UPI ఐడి, WhatsApp, Telegram, "కాల్ చేయండి" అనుమతి లేదు. యాప్ చాట్, కాల్ వాడండి. హెచ్చరిక {n}/2.', 'सर्वांच्या सुरक्षिततेसाठी फोन नंबर, UPI आयडी, WhatsApp, Telegram आणि "कॉल करा" ला परवानगी नाही. अ‍ॅपमधील चॅट आणि कॉल वापरा. इशारा {n}/2.', 'બધાની સલામતી માટે ફોન નંબર, UPI આઈડી, WhatsApp, Telegram અને "કૉલ કરો" ની મંજૂરી નથી. એપની ચેટ અને કૉલ વાપરો. ચેતવણી {n}/2.', 'সবার নিরাপত্তার জন্য ফোন নম্বর, UPI আইডি, WhatsApp, Telegram ও "কল করুন" অনুমোদিত নয়। অ্যাপের চ্যাট ও কল ব্যবহার করুন। সতর্কতা {n}/2।', 'ਸਭ ਦੀ ਸੁਰੱਖਿਆ ਲਈ ਫ਼ੋਨ ਨੰਬਰ, UPI ਆਈਡੀ, WhatsApp, Telegram ਅਤੇ "ਕਾਲ ਕਰੋ" ਦੀ ਆਗਿਆ ਨਹੀਂ। ਐਪ ਦੀ ਚੈਟ ਅਤੇ ਕਾਲ ਵਰਤੋ। ਚੇਤਾਵਨੀ {n}/2।', 'سب ہنز حفاظت خاطرٕ فون نمبر، UPI آئی ڈی، WhatsApp، Telegram تہٕ "کال کرو" ناہ اجازت۔ ایپک چیٹ تہٕ کال استعمال کرو۔ خبردار {n}/2۔', 'سب کی حفاظت کے لیے فون نمبر، UPI آئی ڈی، WhatsApp، Telegram اور "کال کریں" کی اجازت نہیں۔ ایپ کی چیٹ اور کال استعمال کریں۔ وارننگ {n}/2۔'],
  'pcBlockBody': ['Chat and calls are off until {until} because contact details were shared again. Strike {n}. You can still use SOS.', 'संपर्क जानकारी फिर साझा करने से चैट और कॉल {until} तक बंद हैं। स्ट्राइक {n}। SOS अभी भी चलेगा।', 'Contact details phir share karne se chat aur call {until} tak band hain. Strike {n}. SOS chalta rahega.', 'ಸಂಪರ್ಕ ವಿವರ ಮತ್ತೆ ಹಂಚಿದ್ದರಿಂದ ಚಾಟ್ ಮತ್ತು ಕರೆ {until} ವರೆಗೆ ಆಫ್. ಸ್ಟ್ರೈಕ್ {n}. SOS ಬಳಸಬಹುದು.', 'தொடர்பு விவரங்களை மீண்டும் பகிர்ந்ததால் அரட்டை, அழைப்பு {until} வரை நிறுத்தம். ஸ்ட்ரைக் {n}. SOS பயன்படுத்தலாம்.', 'సంప్రదింపు వివరాలు మళ్లీ షేర్ చేసినందున చాట్, కాల్ {until} వరకు ఆఫ్. స్ట్రైక్ {n}. SOS వాడవచ్చు.', 'संपर्क माहिती पुन्हा शेअर केल्याने चॅट आणि कॉल {until} पर्यंत बंद. स्ट्राइक {n}. SOS वापरता येईल.', 'સંપર્ક વિગતો ફરી શેર કરવાથી ચેટ અને કૉલ {until} સુધી બંધ. સ્ટ્રાઇક {n}. SOS વાપરી શકો.', 'যোগাযোগের তথ্য আবার শেয়ার করায় চ্যাট ও কল {until} পর্যন্ত বন্ধ। স্ট্রাইক {n}। SOS ব্যবহার করা যাবে।', 'ਸੰਪਰਕ ਜਾਣਕਾਰੀ ਮੁੜ ਸਾਂਝੀ ਕਰਨ ਕਰਕੇ ਚੈਟ ਅਤੇ ਕਾਲ {until} ਤੱਕ ਬੰਦ। ਸਟ੍ਰਾਈਕ {n}। SOS ਵਰਤ ਸਕਦੇ ਹੋ।', 'رابطہ تفصیل پتہٕ شیئر کرنہ کرِتھ چیٹ تہٕ کال {until} تام بند۔ سٹرائک {n}۔ SOS استعمال کٔرتھ ہیکو۔', 'رابطے کی تفصیل دوبارہ شیئر کرنے سے چیٹ اور کال {until} تک بند ہیں۔ اسٹرائیک {n}۔ SOS استعمال کر سکتے ہیں۔'],
  'pcReviewNote': ['An admin will review your account.', 'एडमिन आपके खाते की समीक्षा करेगा।', 'Admin aapke account ki review karega.', 'ನಿರ್ವಾಹಕರು ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ.', 'நிர்வாகி உங்கள் கணக்கை மதிப்பாய்வு செய்வார்.', 'అడ్మిన్ మీ ఖాతాను సమీక్షిస్తారు.', 'अ‍ॅडमिन तुमच्या खात्याची तपासणी करेल.', 'એડમિન તમારા ખાતાની સમીક્ષા કરશે.', 'অ্যাডমিন আপনার অ্যাকাউন্ট পর্যালোচনা করবেন।', 'ਐਡਮਿਨ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਕਰੇਗਾ।', 'ایڈمن چھ تُہنز اکاؤنٹ ریویو کران۔', 'ایڈمن آپ کے اکاؤنٹ کا جائزہ لے گا۔'],
  'pcNotRecorded': ['The warning could not be saved. Check your internet and your phone\'s date and time.', 'चेतावनी सहेजी नहीं जा सकी। इंटरनेट और फ़ोन की तारीख़-समय जाँचें।', 'Chetavni save nahi ho saki. Internet aur phone ki date-time check karein.', 'ಎಚ್ಚರಿಕೆ ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಇಂಟರ್ನೆಟ್ ಮತ್ತು ಫೋನ್ ದಿನಾಂಕ-ಸಮಯ ಪರಿಶೀಲಿಸಿ.', 'எச்சரிக்கையைச் சேமிக்க முடியவில்லை. இணையம், தொலைபேசி தேதி-நேரத்தைச் சரிபார்க்கவும்.', 'హెచ్చరికను సేవ్ చేయలేకపోయాం. ఇంటర్నెట్, ఫోన్ తేదీ-సమయం తనిఖీ చేయండి.', 'इशारा जतन करता आला नाही. इंटरनेट आणि फोनची तारीख-वेळ तपासा.', 'ચેતવણી સાચવી શકાઈ નથી. ઇન્ટરનેટ અને ફોનની તારીખ-સમય તપાસો.', 'সতর্কতা সংরক্ষণ করা যায়নি। ইন্টারনেট ও ফোনের তারিখ-সময় দেখুন।', 'ਚੇਤਾਵਨੀ ਸੰਭਾਲੀ ਨਹੀਂ ਜਾ ਸਕੀ। ਇੰਟਰਨੈੱਟ ਅਤੇ ਫ਼ੋਨ ਦੀ ਤਾਰੀਖ਼-ਸਮਾਂ ਵੇਖੋ।', 'خبردار محفوظ کٔرتھ ناہ ہیکو۔ انٹرنیٹ تہٕ فونک تاریخ-وقت وُچھو۔', 'وارننگ محفوظ نہیں ہو سکی۔ انٹرنیٹ اور فون کی تاریخ و وقت جانچیں۔'],
  'pcBlockedBanner': ['Chat and calls are off until {until} because contact details were shared. SOS still works.', 'संपर्क जानकारी साझा करने से चैट और कॉल {until} तक बंद हैं। SOS चलता है।', 'Contact details share karne se chat aur call {until} tak band hain. SOS chalta hai.', 'ಸಂಪರ್ಕ ವಿವರ ಹಂಚಿದ್ದರಿಂದ ಚಾಟ್ ಮತ್ತು ಕರೆ {until} ವರೆಗೆ ಆಫ್. SOS ಕೆಲಸ ಮಾಡುತ್ತದೆ.', 'தொடர்பு விவரங்களைப் பகிர்ந்ததால் அரட்டை, அழைப்பு {until} வரை நிறுத்தம். SOS வேலை செய்யும்.', 'సంప్రదింపు వివరాలు షేర్ చేసినందున చాట్, కాల్ {until} వరకు ఆఫ్. SOS పనిచేస్తుంది.', 'संपर्क माहिती शेअर केल्याने चॅट आणि कॉल {until} पर्यंत बंद. SOS चालते.', 'સંપર્ક વિગતો શેર કરવાથી ચેટ અને કૉલ {until} સુધી બંધ. SOS ચાલે છે.', 'যোগাযোগের তথ্য শেয়ার করায় চ্যাট ও কল {until} পর্যন্ত বন্ধ। SOS কাজ করে।', 'ਸੰਪਰਕ ਜਾਣਕਾਰੀ ਸਾਂਝੀ ਕਰਨ ਕਰਕੇ ਚੈਟ ਅਤੇ ਕਾਲ {until} ਤੱਕ ਬੰਦ। SOS ਚੱਲਦਾ ਹੈ।', 'رابطہ تفصیل شیئر کرنہ کرِتھ چیٹ تہٕ کال {until} تام بند۔ SOS چھ کم کران۔', 'رابطے کی تفصیل شیئر کرنے سے چیٹ اور کال {until} تک بند ہیں۔ SOS کام کرتا ہے۔'],
  'pcHidden': ['Phone numbers are private on {app}. Use Chat or the in-app Call button.', '{app} पर फ़ोन नंबर निजी हैं। चैट या ऐप के कॉल बटन का उपयोग करें।', '{app} par phone number private hain. Chat ya app ke Call button ka use karein.', '{app} ನಲ್ಲಿ ಫೋನ್ ಸಂಖ್ಯೆಗಳು ಖಾಸಗಿ. ಚಾಟ್ ಅಥವಾ ಆ್ಯಪ್ ಕರೆ ಬಟನ್ ಬಳಸಿ.', '{app} இல் தொலைபேசி எண்கள் தனிப்பட்டவை. அரட்டை அல்லது செயலி அழைப்பு பொத்தானைப் பயன்படுத்துங்கள்.', '{app} లో ఫోన్ నంబర్లు ప్రైవేట్. చాట్ లేదా యాప్ కాల్ బటన్ వాడండి.', '{app} वर फोन नंबर खाजगी आहेत. चॅट किंवा अ‍ॅपचे कॉल बटण वापरा.', '{app} પર ફોન નંબર ખાનગી છે. ચેટ અથવા એપનું કૉલ બટન વાપરો.', '{app}-তে ফোন নম্বর গোপন। চ্যাট বা অ্যাপের কল বোতাম ব্যবহার করুন।', '{app} ਤੇ ਫ਼ੋਨ ਨੰਬਰ ਨਿੱਜੀ ਹਨ। ਚੈਟ ਜਾਂ ਐਪ ਦਾ ਕਾਲ ਬਟਨ ਵਰਤੋ।', '{app} پیٹھ فون نمبر نجی چھ۔ چیٹ یا ایپک کال بٹن استعمال کرو۔', '{app} پر فون نمبر نجی ہیں۔ چیٹ یا ایپ کا کال بٹن استعمال کریں۔'],
  'pcCall': ['Call', 'कॉल', 'Call', 'ಕರೆ', 'அழைப்பு', 'కాల్', 'कॉल', 'કૉલ', 'কল', 'ਕਾਲ', 'کال', 'کال'],
